-- SYNTHETIC secrets only. Execute via Lovable inside BEGIN ... ROLLBACK after 0097.
-- No environment secret is read, printed, persisted or generated by this test.
INSERT INTO public_bot.gateway_credentials(key_hash,label,expires_at)
 VALUES(sha256(convert_to('synthetic-test-key-256-bits-do-not-use-in-production-000000000001','UTF8')),'synthetic-gateway-active',now()+interval '1 hour'),
 (sha256(convert_to('synthetic-test-key-256-bits-do-not-use-in-production-000000000002','UTF8')),'synthetic-gateway-expired',now()+interval '1 hour'),
 (sha256(convert_to('synthetic-test-key-256-bits-do-not-use-in-production-000000000003','UTF8')),'synthetic-gateway-revoked',now()+interval '1 hour');
UPDATE public_bot.gateway_credentials SET created_at=now()-interval '2 hours',expires_at=now()-interval '1 hour' WHERE label='synthetic-gateway-expired';
UPDATE public_bot.gateway_credentials SET revoked_at=now() WHERE label='synthetic-gateway-revoked';
SET LOCAL ROLE anon;
DO $$ BEGIN
 BEGIN PERFORM public.public_bot_gateway('configuration','{"b":"cordial"}'); RAISE EXCEPTION 'missing gateway key accepted'; EXCEPTION WHEN SQLSTATE 'PT401' THEN NULL; END;
 PERFORM set_config('request.headers','{"x-public-bot-key":"synthetic-test-key-256-bits-do-not-use-in-production-INVALID0000"}',true);
 BEGIN PERFORM public.public_bot_gateway('configuration','{"b":"cordial"}'); RAISE EXCEPTION 'invalid gateway key accepted'; EXCEPTION WHEN SQLSTATE 'PT401' THEN NULL; END;
 PERFORM set_config('request.headers','{"x-public-bot-key":"synthetic-test-key-256-bits-do-not-use-in-production-000000000002"}',true);
 BEGIN PERFORM public.public_bot_gateway('configuration','{"b":"cordial"}'); RAISE EXCEPTION 'expired gateway key accepted'; EXCEPTION WHEN SQLSTATE 'PT401' THEN NULL; END;
 PERFORM set_config('request.headers','{"x-public-bot-key":"synthetic-test-key-256-bits-do-not-use-in-production-000000000003"}',true);
 BEGIN PERFORM public.public_bot_gateway('configuration','{"b":"cordial"}'); RAISE EXCEPTION 'revoked gateway key accepted'; EXCEPTION WHEN SQLSTATE 'PT401' THEN NULL; END;
END $$;
SELECT set_config('request.headers','{"x-public-bot-key":"synthetic-test-key-256-bits-do-not-use-in-production-000000000001"}',true) IS NOT NULL AS synthetic_header_installed;
DO $$ DECLARE r jsonb; err text; BEGIN
 r:=public.public_bot_gateway('configuration','{"b":"cordial"}');
 IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR NOT r ?& ARRAY['enabled','voice','trends','whatsapp'] THEN RAISE EXCEPTION 'valid gateway credential rejected'; END IF;
 r:=public.public_bot_gateway('candidates','{"b":"cordial","f":{"reference":"x''); DROP TABLE public.properties; --"}}');
 IF r<>'[]'::jsonb THEN RAISE EXCEPTION 'SQL-like literal did not remain a filter literal'; END IF;
 BEGIN PERFORM public.public_bot_gateway('public.properties','{"b":"cordial"}'); RAISE EXCEPTION 'unknown operation accepted'; EXCEPTION WHEN SQLSTATE 'PT400' THEN NULL; END;
 BEGIN PERFORM public.public_bot_gateway('configuration','{"b":"cordial","tenant":"morar"}'); RAISE EXCEPTION 'extra authority key accepted'; EXCEPTION WHEN SQLSTATE 'PT400' THEN NULL; END;
 BEGIN PERFORM public.public_bot_gateway('configuration','{"b":"gestao"}'); RAISE EXCEPTION 'invalid brand accepted'; EXCEPTION WHEN SQLSTATE 'PT400' THEN NULL; END;
 BEGIN PERFORM public.public_bot_gateway('configuration','{}'); RAISE EXCEPTION 'required argument omitted'; EXCEPTION WHEN SQLSTATE 'PT400' THEN NULL; END;
 BEGIN PERFORM public.public_bot_gateway('open_session','{"b":"cordial","token_hash":"oops","ip_key":"oops"}'); RAISE EXCEPTION 'malformed credential/hash accepted'; EXCEPTION WHEN SQLSTATE 'PT400' THEN NULL; END;
 BEGIN PERFORM public.public_bot_gateway('accept_turn','{"b":"cordial","token_hash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","ip_key":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","local_day":"2026-99-99","request_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","expected_revision":0,"fingerprint":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}'); RAISE EXCEPTION 'invalid typed date accepted'; EXCEPTION WHEN SQLSTATE 'PT400' THEN GET STACKED DIAGNOSTICS err=MESSAGE_TEXT; IF err<>'Invalid request' THEN RAISE EXCEPTION 'internal error escaped gateway'; END IF; END;
 BEGIN PERFORM public.public_bot_gateway('resolve','{"b":"cordial","ids":["not-a-uuid"]}'); RAISE EXCEPTION 'invalid ID accepted'; EXCEPTION WHEN SQLSTATE 'PT400' THEN NULL; END;
 BEGIN PERFORM public.public_bot_gateway('configuration',jsonb_build_object('b','cordial','padding',repeat('x',33000))); RAISE EXCEPTION 'oversized body accepted'; EXCEPTION WHEN SQLSTATE 'PT400' THEN NULL; END;
 -- Anonymous visitors cannot bypass the gateway into tables or an arbitrary private RPC.
 BEGIN PERFORM 1 FROM public_bot.gateway_credentials; RAISE EXCEPTION 'anonymous read of credential hash'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public_bot.source('cordial',NULL); RAISE EXCEPTION 'anonymous source RPC execution'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
END $$;
-- Exercise every dispatcher branch with synthetic session/request identities.
DO $$ DECLARE r jsonb; draft jsonb; token text:=repeat('b',64); ip text:=repeat('c',64);
 req uuid:='bbbbbbbb-bbbb-4bbb-8bbb-000000000097'; voice_req uuid:='bbbbbbbb-bbbb-4bbb-8bbb-000000000098';
 day text:=((now() AT TIME ZONE 'America/Sao_Paulo')::date)::text;
BEGIN
 r:=public.public_bot_gateway('facets','{"b":"cordial"}');
 IF jsonb_typeof(r->'types') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'facets dispatch failed'; END IF;
 r:=public.public_bot_gateway('suggestion_set','{"b":"morar"}');
 IF jsonb_typeof(r->'suggestions') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'suggestions dispatch failed'; END IF;
 IF public.public_bot_gateway('resolve','{"b":"morar","ids":[]}') IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'resolve dispatch failed'; END IF;
 r:=public.public_bot_gateway('open_session',jsonb_build_object('b','cordial','token_hash',token,'ip_key',ip));
 draft:=r->'draft';
 IF (draft->>'revision')::integer<>0 THEN RAISE EXCEPTION 'open dispatch failed'; END IF;
 IF public.public_bot_gateway('read_session',jsonb_build_object('b','morar','token_hash',token)) IS NOT NULL THEN RAISE EXCEPTION 'gateway crossed session brand'; END IF;
 r:=public.public_bot_gateway('accept_turn',jsonb_build_object('b','cordial','token_hash',token,'ip_key',ip,'local_day',day,'request_id',req,'expected_revision',0,'fingerprint',repeat('d',64)));
 IF r->>'state' IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'accept dispatch failed'; END IF;
 IF public.public_bot_gateway('reserve_cost',jsonb_build_object('b','cordial','token_hash',token,'request_id',req)) IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'cost dispatch failed'; END IF;
 IF public.public_bot_gateway('reserve_cost',jsonb_build_object('b','cordial','token_hash',token,'request_id',req)) IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'gateway paid twice'; END IF;
 draft:=jsonb_set(draft,'{revision}','1');
 IF public.public_bot_gateway('complete_turn',jsonb_build_object('b','cordial','token_hash',token,'request_id',req,'result',jsonb_build_object('requestId',req,'draft',draft,'cards','[]'::jsonb,'answer','Resposta sintética de teste','exhausted',false,'unavailable',false))) IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'complete dispatch failed'; END IF;
 r:=public.public_bot_gateway('read_session',jsonb_build_object('b','cordial','token_hash',token));
 IF jsonb_array_length(r->'turns')<>1 OR r->'draft'->>'revision'<>'1' THEN RAISE EXCEPTION 'persisted gateway result missing'; END IF;
 r:=public.public_bot_gateway('accept_turn',jsonb_build_object('b','cordial','token_hash',token,'ip_key',ip,'local_day',day,'request_id',req,'expected_revision',0,'fingerprint',repeat('d',64)));
 IF r->>'state' IS DISTINCT FROM 'replay' THEN RAISE EXCEPTION 'gateway retry not idempotent'; END IF;
 r:=public.public_bot_gateway('take_voice',jsonb_build_object('b','cordial','token_hash',token,'ip_key',ip,'local_day',day,'request_id',voice_req,'bytes',1000,'seconds',60));
 IF r->>'state' IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'voice dispatch failed'; END IF;
 IF public.public_bot_gateway('finish_voice',jsonb_build_object('b','cordial','token_hash',token,'request_id',voice_req,'ok',false)) IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'voice finish dispatch failed'; END IF;
 IF public.public_bot_gateway('event',jsonb_build_object('b','cordial','token_hash',token,'event',jsonb_build_object('consent',false))) IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'gateway consent ignored'; END IF;
 IF public.public_bot_gateway('usage',jsonb_build_object('b','cordial','request_id',req,'model','synthetic-test','latency',10,'input_tokens',1,'output_tokens',1,'code','ok')) IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'usage dispatch failed'; END IF;
END $$;
RESET ROLE;
SET LOCAL ROLE public_bot_runtime;
DO $$ BEGIN
 BEGIN PERFORM 1 FROM public.properties; RAISE EXCEPTION 'runtime entered properties'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM 1 FROM public.clients; RAISE EXCEPTION 'runtime entered clients'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM 1 FROM public_bot.gateway_credentials; RAISE EXCEPTION 'runtime read credential hash'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM 1 FROM public_bot.sessions; RAISE EXCEPTION 'runtime read another session directly'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public_bot.source('cordial',NULL); RAISE EXCEPTION 'runtime called source'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
END $$;
RESET ROLE;
DO $$ BEGIN
 IF has_schema_privilege('public_bot_runtime','public','USAGE') OR has_schema_privilege('public_bot_runtime','auth','USAGE') OR has_schema_privilege('anon','public_bot','USAGE') OR pg_has_role('public_bot_runtime','public_bot_owner','MEMBER') THEN RAISE EXCEPTION 'gateway widened runtime role'; END IF;
 IF has_function_privilege('authenticated','public.public_bot_gateway(text,jsonb)','EXECUTE') OR has_function_privilege('service_role','public.public_bot_gateway(text,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'gateway leaked default grants'; END IF;
 IF has_function_privilege('anon','public_bot.gateway_authorize()','EXECUTE') OR has_function_privilege('authenticated','public_bot.gateway_authorize()','EXECUTE') OR has_function_privilege('service_role','public_bot.gateway_authorize()','EXECUTE') OR has_column_privilege('service_role','public_bot.gateway_credentials','key_hash','SELECT') THEN RAISE EXCEPTION 'gateway credential access leaked'; END IF;
END $$;
SELECT jsonb_build_object('missing_key','denied','invalid_key','denied','expired_key','denied','revoked_key','denied','valid_key','accepted','unknown_operations','denied','extra_scope','denied','dispatcher_14_operations','passed','idempotent_paid_reservation','passed','session_brand_isolation','passed','typed_arguments','validated','sql_injection_literal','inert','errors','sanitized','private_tables','denied','arbitrary_rpc','denied','owner_membership','absent','schema_exposure','unchanged','transaction','ROLLBACK required') AS gateway_integration;
